dict(task="1.4",
stem="Two months after moving to AWS, an engineering firm's monitoring shows that most of its EC2 instances average under 10% CPU use and never pass 30%, even at month-end. Which action is rightsizing?",
options=["Buy three-year Reserved Instances for the instances at their current sizes",
 "Move each instance to a smaller instance type that still covers its measured peak",
 "Raise the maximum size of each Auto Scaling group",
 "Move the instances to Dedicated Hosts"], answer="B",
expl="Rightsizing means choosing the type, size and number of resources that meet measured needs at the lowest cost; AWS Compute Optimizer can recommend sizes from the same data. Reserved Instances are tempting because they lower the rate, but committing at today's oversized types locks in the waste, so rightsize first and commit afterwards. A larger Auto Scaling maximum and Dedicated Hosts add capacity or cost rather than trimming them.",
links=[("02-why-the-cloud/04-what-a-data-center-really-costs.md", "Rightsizing and automation keep the variable bill small"),
       ("13-moving-to-aws/04-the-business-case.md", "Rightsize twice: before the move from measured data, and after it with Compute Optimizer")]),
